@spec keyDispatch_spec  src=tests/specs/keyDispatch_spec.lua  loc=236  cases=11
@exercises commandManager (cmgr)
@surface   cmgr:registerAll, cmgr:bind, cmgr:scope, cmgr:push, cmgr:beginPrefix, cmgr:isPrefixActive

# Intent
  keyDispatch: the prefix-capture + keychain walk extracted from coordinator
  (design/fx-patterns.md P3 step a). Now an importable module the fx-pattern
  mini modal reuses, so pin the dispatch contract directly: consume/first-hit,
  commandHeld hold-tracking, the acceptCmds gate, prefix capture + finish,
  false-declines, and the pageSuppressed root narrowing.

# Helpers
  @fn setKeys(opts)  @ 23-27
      -- A pressed key is also down; `down` alone models a hold with no fresh press.
  @fn loadKD()  @ 33-38
      -- Rebind imgui to ours before loading keyDispatch: earlier specs' module-load
      -- preloads cache a different fake, so nil both and re-require (curveEditor idiom).
  @fn freshCmgr()  @ 42-56
      -- Fresh real cmgr with commands bound to bare (Mod_None) keys; the returned log
      -- records which bodies ran and the last prefix arg one received.

# Cases
  @case 'a scope capturing letters takes them ahead of the keychain walk'  [pure]  @ 64-87
  @case 'a pressed bound key fires its command, consumes, and reports as held'  [pure]  @ 91-100
  @case 'acceptCmds=false short-circuits: nothing dispatched'  [pure]  @ 104-112
  @case 'a held (not freshly pressed) bound key reports in commandHeld but does not fire'  [pure]  @ 116-125
  @case 'a digit while a prefix is open is captured, not dispatched'  [pure]  @ 129-139
  @case 'with a prefix open, a bound key freezes the prefix, dispatches, and clears it'  [pure]  @ 143-155
  @case 'a command returning false declines: not consumed, key released from commandHeld'  [pure]  @ 159-168
  @case 'pageSuppressed narrows the walk to root: page bindings die, globals live'  [pure]  @ 172-192
  @case 'a shift-chord binding fires under shift and reports held'  [pure]  @ 196-207
  @case 'the same key pressed bare ignores the shift binding entirely'  [pure]  @ 211-222
  @case 'held marking follows the live chord: bare binding unmarked while shift is down'  [pure]  @ 226-234

